{
  "missionStatement": "Study superconducting materials via online research and update the repository's chemistry and physics proposal for discovering and manufacturing room-temperature superconducting compounds.",
  "criteria": [
    {
      "description": "Online research summary (docs/online_research_summary.md) is updated with summaries of at least 10 recent papers (2020-2025) on room-temperature superconductivity, each with a citation.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "proposed_chemistry_physics.md is updated to present a coherent chemistry and physics framework for discovering and manufacturing room-temperature superconducting compounds, referencing online research.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "literature_review.md is updated to include at least 5 new papers from online research with proper citations and key findings.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "theoretical_framework.md is updated to incorporate recent theoretical models (e.g., Eliashberg theory for hydrides, nickelate analogies) from online research.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "candidate_materials.md is updated with new candidate compounds and their predicted Tc values from online research, including at least 3 new entries.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "synthesis_methods.md is updated with new high-pressure synthesis techniques (e.g., diamond anvil cell, laser heating) and doping methods from online research.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "characterization_techniques.md is updated with new measurement methods (e.g., muon spin rotation, neutron scattering) from online research.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "manufacturing_scalability.md (docs/) is updated with insights on large-scale synthesis and commercialization from online research.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "discovery_strategy.md is updated to incorporate new approaches (e.g., machine learning screening, high-throughput experimentation) from online research.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "roadmap.md is updated to reflect new milestones and timelines based on findings from online research.",
      "expectedFiles": ["roadmap.md"]
    }
  ]
}
